const data = $json;
const workflow = data.workflow || {};
const execution = data.execution || {};
const error = execution.error || {};
const subject = `n8n failure: ${workflow.name || workflow.id || 'unknown workflow'}`;
const lines = [
  'An n8n workflow failed.',
  '',
  `Workflow: ${workflow.name || '(unknown)'}`,
  `Workflow ID: ${workflow.id || '(unknown)'}`,
  `Execution ID: ${execution.id || '(unknown)'}`,
  `Mode: ${execution.mode || '(unknown)'}`,
  `Last node: ${execution.lastNodeExecuted || '(unknown)'}`,
  `Error: ${error.message || '(no message)'}`,
];
if (execution.url) lines.push(`Execution URL: ${execution.url}`);
if (error.stack) {
  lines.push('', 'Stack:', String(error.stack).slice(0, 3000));
}
return [{ json: { subject, body: lines.join('\n') } }];
